cat > src/lib/users.ts <<'EOF'
import { headers } from "next/headers";
import { auth, db } from "@/lib/auth";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

type UserRow = { id: string; email: string; name: string; createdAt: string };

function toUser(row: UserRow): User {
  return { ...row, createdAt: new Date(row.createdAt).toISOString().slice(0, 10) };
}

export async function listUsers(): Promise<User[]> {
  const rows = db
    .prepare('SELECT id, email, name, createdAt FROM "user" ORDER BY createdAt')
    .all() as UserRow[];
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const row = db
    .prepare('SELECT id, email, name, createdAt FROM "user" WHERE id = ?')
    .get(id) as UserRow | undefined;
  return row && toUser(row);
}

// Resolves the signed-in user from the session cookie; undefined if signed out.
export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth.api.getSession({ headers: await headers() });
  if (!session) return undefined;
  const { id, email, name, createdAt } = session.user;
  return toUser({ id, email, name, createdAt: createdAt.toISOString() });
}
EOF
cat > src/components/auth-form.tsx <<'EOF'
"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { authClient } from "@/lib/auth-client";

const input = "w-full rounded border border-black/20 bg-transparent px-3 py-2 text-sm dark:border-white/25";
const button = "w-full rounded bg-foreground px-3 py-2 text-sm font-medium text-background disabled:opacity-50";

export function AuthForm({ mode }: { mode: "sign-in" | "sign-up" }) {
  const router = useRouter();
  const [error, setError] = useState("");
  const [pending, setPending] = useState(false);
  const signUp = mode === "sign-up";

  async function onSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const form = new FormData(e.currentTarget);
    const email = String(form.get("email"));
    const password = String(form.get("password"));
    setError("");
    setPending(true);
    const { error } = signUp
      ? await authClient.signUp.email({ email, password, name: String(form.get("name")) })
      : await authClient.signIn.email({ email, password });
    setPending(false);
    if (error) return setError(error.message ?? "Something went wrong");
    router.push("/dashboard");
    router.refresh();
  }

  return (
    <main className="mx-auto max-w-sm space-y-4 p-8">
      <h1 className="text-2xl font-semibold">{signUp ? "Create your account" : "Sign in to Notely"}</h1>
      <form onSubmit={onSubmit} className="space-y-3">
        {signUp && <input name="name" placeholder="Name" required className={input} />}
        <input name="email" type="email" placeholder="Email" required className={input} />
        <input name="password" type="password" placeholder="Password (min 8 chars)" minLength={8} required className={input} />
        {error && <p role="alert" className="text-sm text-red-600">{error}</p>}
        <button disabled={pending} className={button}>{signUp ? "Sign up" : "Sign in"}</button>
      </form>
      <button
        type="button"
        className={button}
        onClick={() => authClient.signIn.social({ provider: "google", callbackURL: "/dashboard" })}
      >
        Continue with Google
      </button>
      <p className="text-sm opacity-70">
        {signUp ? "Have an account? " : "No account? "}
        <Link className="underline" href={signUp ? "/sign-in" : "/sign-up"}>
          {signUp ? "Sign in" : "Sign up"}
        </Link>
      </p>
    </main>
  );
}
EOF
